commands:
node -e '
const p=require("./.scratch/ultima-init-plan.json");
for (const o of p.operations) console.log(o.id, "|", o.kind, "|", o.path||"", o.command? (o.command.command+" "+o.command.args.join(" ")):"");
const rest={...p}; delete rest.operations; delete rest.payloads; delete rest.dependencies;
console.log(JSON.stringify(rest,null,1).slice(0,5000));
'

grep -n "defaultTagName\|'span'" components/ui/badge.tsx; cat > app/page.tsx <<'EOF'
import Pantry from '@/components/pantry/pantry';

export default function Home() {
  return <Pantry />;
}
EOF
rm app/setup-check.tsx
cat > app/layout.tsx <<'EOF'
import type { Metadata } from "next";
import "./globals.css";
import "./ultima.css";
import "../ultima-theme.css";

export const metadata: Metadata = {
  title: "Pantry · Larder",
  description: "Stock and donations for the neighbourhood food pantry.",
};

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  );
}
EOF
npx ultima-design check --files app/page.tsx app/layout.tsx components/pantry/pantry.tsx components/pantry/pantry-data.ts components/pantry/pantry.stylex.ts; echo exit=$?

cat > eslint.config.mjs <<'EOF'
import tseslint from 'typescript-eslint';
import { ultimaStylex } from './ultima.eslint.mjs';

export default [
  { ignores: ['**/node_modules/**', '**/dist/**', '**/.next/**', '**/out/**', '**/coverage/**'] },
  {
    files: ultimaStylex.files,
    languageOptions: {
      parser: tseslint.parser,
      parserOptions: { ecmaFeatures: { jsx: true } },
    },
  },
  ultimaStylex,
];
EOF
npm pkg set scripts.lint="eslint ." && cat package.json && for f in app/page.tsx components/pantry/pantry.tsx components/ui/select.tsx lib/tokens.stylex.ts components/pantry/pantry.stylex.ts; do printf "%s: " $f; npx --no-install eslint --print-config $f | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{const c=JSON.parse(s);console.log(c.languageOptions?.parser, JSON.stringify(c.rules?.["@stylexjs/valid-styles"]))})'; done; npm run lint; echo lint_exit=$?
